          "condition": {
            "mode": "glide_scripted_query",
            "value": "(function execute(table) {\n    /* Code your glide record query logic here. For example:\n\n        var options = [];\n        var gr = new GlideRecordSecure(table);\n        gr.addEncodedQuery('active=true^numberSTARTSWITHINC001001');\n        gr.setLimit(10);\n        gr.query();\n        while(gr.next()) {\n            options.push({ 'value': gr.getUniqueValue(), 'label': gr.getValue('short_description') });\n        }\n        return options;\n    */\n\n    var options = []; // add options here...\n    var grNI = new GlideRecord(table);\n    grNI.addQuery('u_request_type',vaInputs.needit_type.getValue());\n    grNI.addQuery('active','true');\n    grNI.addQuery('u_requested_for',vaInputs.user);\n    grNI.orderBy('u_when_needed');\n    grNI.query();\n\n    while (grNI.next()) {\n        options.push(\n            { \n                'value': grNI.getUniqueValue(),\n                'label': grNI.getValue('number') +\n                \" (\" + grNI.getDisplayValue('u_when_needed') +\n                \"): \" + grNI.getValue('short_description')\n            }\n        );\n    }\n\n    return options;\n})(table)\n"
          },
