        "fbb70682c1f845c88c8647f21be68880": {
          "id": "fbb70682c1f845c88c8647f21be68880",
          "name": "Update search_count",
          "script": "(function execute() {\n    /* Code your scripted action here. For example, you might update a\n       record based on conditional logic:\n\n        if (vaVars.my_flag == 'say hello') {\n            gs.info('hi there');\n        } else {\n            gs.info('bye now');\n        }\n    */\n\n    vaVars.search_count++;\n})()\n",
