        "22acb2ab7db649c0b70daf8142f49ea5": {
          "id": "22acb2ab7db649c0b70daf8142f49ea5",
          "stepType": "TextOutput",
          "name": "Limit Reached",
          "secure": false,
          "value": [
            {
              "value": "(function execute() {\n    // If Live Chat is available, inform users they will be transfered to a live agent\n    // otherwise, let them know how to work with more NeedIt records\n    if (vaSystem.isLiveAgentAvailable()) {\n        return 'You have reached your NeedIt search limit. I will transfer you to a live agent for assistance.'\n    } else {\n        return 'You have reached your NeedIt search limit. If you need to work with multiple NeedIt records, open NeedIt > My NeedIt Requests.'\n    }\n})()",
              "mode": "script"
            }
          ],
          "requestFeedback": true,
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
        "6894b62c7ea9416d8f13dd4bafda884a": {
          "id": "6894b62c7ea9416d8f13dd4bafda884a",
          "name": "Transfer to Agent",
          "script": "(function execute() {\n    // Transfer to a live agent\n    vaSystem.connectToAgent()\n})()",
          "stepType": "ScriptAction",
          "applicability": {
            "mode": "script",
            "value": "(function execute() {\n    // If Live Chat is available, return true\n    // otherwise, return false\n    if (vaSystem.isLiveAgentAvailable()) {\n        return true;\n    } else {\n        return false;\n    }\n})()"
          }
        }
